291	// TestCompatTamperedByteRejected changes exactly one protected field of
292	// the material read back from the frozen archive — the lone 0xFF becomes
293	// 0xFE or a genuine U+FFFD — while every record fingerprint and the saved
294	// checkpoint stay untouched. Chain validation and offline review must both
295	// refuse with ErrInvalidRange, and the review must deliver no conclusion.
296	func TestCompatTamperedByteRejected(t *testing.T) {
297		replacements := map[string]string{"0xFE": "\xfe", "U+FFFD": "\uFFFD"}
298		fields := map[string]func([]AuditRecord, string){
299			"published policy id": func(recs []AuditRecord, repl string) {
300				p := &recs[2].Change.Policies[0]
301				p.ID = strings.Replace(p.ID, "\xff", repl, 1)
302			},
303			"decision subject id": func(recs []AuditRecord, repl string) {
304				id := &recs[3].Decision.Request.Subject.ID
305				*id = strings.Replace(*id, "\xff", repl, 1)
306			},
307		}
308		for field, mutate := range fields {
309			for replName, repl := range replacements {
310				t.Run(field+"/"+replName, func(t *testing.T) {
311					recs := compatRecords(t)
312					mutate(recs, repl)
313					// Fingerprints and the checkpoint are the saved ones;
314					// only the one field's bytes differ.
315					if recs[2].Fingerprint != compatRecordFingerprints[2] ||
316						recs[3].Fingerprint != compatRecordFingerprints[3] {
317						t.Fatal("test premise broken: record fingerprints must stay as saved")
318					}
319					if err := VerifyAudit(compatOrg, recs, compatCheckpoint); !errors.Is(err, ErrInvalidRange) {
320						t.Fatalf("VerifyAudit err = %v, want ErrInvalidRange", err)
321					}
322					got, err := RecheckDecisionOffline(compatOrg, recs, compatCheckpoint, 2)
323					if !errors.Is(err, ErrInvalidRange) {
324						t.Fatalf("RecheckDecisionOffline err = %v, want ErrInvalidRange", err)
325					}
326					if !reflect.DeepEqual(got, OfflineDecisionReview{}) {
327						t.Fatalf("tampered material delivered a partial conclusion: %+v", got)
328					}
329				})
330			}
331		}
332	}
